settings.CUSTOM_UI:
function Information() {
    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8, fontSize: 12, color: '#666' }}>
            <div>
                Select Device to use an existing Modbus Master device. Leave Device empty to define a direct Serial or TCP connection with the no-device connection fields.
            </div>
            <div>
                Function Code may be a number or a numeric variable. Read codes 1 to 4 return data; write codes 5 and 6 write Data and return the written value.
            </div>
            <div style={{ whiteSpace: 'pre-line' }}>
                {'Output:\n' +
                 'response_data (Number): value read or written.\n' +
                 'device_id (Number): target Modbus unit id.\n' +
                 'register_address (Number): target register or coil address.\n' +
                 'error (Number): 0 on success; negative errno on failure.'}
            </div>
        </div>
    );
}

return Information;

settings.CODE:
/* Modbus Request (dynamic function code) - block mbreq_{{feature.settings.ID}}
 *
 * Connection resolved at code generation (mirrors ModbusMaster/zephyr.ts bus numbering):
 *   MBREQ_<ID>_DYNAMIC_TCP 1  host/port are evaluated on every trigger and the socket
 *                             comes from the shared TCP pool (needs a Modbus Master).
 *   MBREQ_<ID>_DYNAMIC_TCP 0  fixed client MBREQ_<ID>_CLIENT: the linked device's bus,
 *                             or the serial port's bus when no device is linked.
 *   MBREQ_<ID>_DEVICE_UNIT_ID defined when a serial device is linked: its unit id wins. */
{{
(function () {
    var id = feature.settings.ID;
    var devRef = feature.settings.DEVICE || '';
    var master = project.features.filter(function (f) { return f.id === 'modbus_master'; })[0];
    var devices = master ? (master.settings.MODBUSDEVICES || []) : [];
    var rtuBus = {};
    var nextRtu = 0;
    var nextTcp = 0;
    var clientOf = {};
    devices.forEach(function (d) {
        var s = d.settings;
        if (s.PROTOCOL === 'modbus_RTU') {
            if (rtuBus[s.SERIAL_PORT] === undefined) { rtuBus[s.SERIAL_PORT] = nextRtu; nextRtu += 1; }
            clientOf[s.ID] = 'mb_client_rtu_' + rtuBus[s.SERIAL_PORT];
        } else {
            clientOf[s.ID] = 'mb_client_tcp_' + nextTcp;
            nextTcp += 1;
        }
    });
    /* A referenced feature shows up as its name in this context, and as its id in
     * the trigger context, so accept both. */
    var device = devices.filter(function (d) {
        return devRef !== '' && (d.settings.ID === devRef || d.settings.NAME === devRef);
    })[0];
    var lines = [];
    if (device) {
        lines.push('#define MBREQ_' + id + '_DYNAMIC_TCP 0');
        lines.push('#define MBREQ_' + id + '_CLIENT ' + clientOf[device.settings.ID]);
        if (device.settings.PROTOCOL === 'modbus_RTU') {
            lines.push('#define MBREQ_' + id + '_DEVICE_UNIT_ID (' + device.settings.DEVICEID + ')');
        }
        return lines.join('\n');
    }
    if (feature.settings.PROTOCOL === 'modbus_TCP') {
        lines.push('#define MBREQ_' + id + '_DYNAMIC_TCP 1');
        lines.push('#define MBREQ_' + id + '_CLIENT (-1)');
        return lines.join('\n');
    }
    /* Dynamic serial: join the bus of the selected serial port. Node-defined serial
     * buses are numbered after the device buses, in project order. */
    var requestBlockIds = {};
    project.features.forEach(function (f) {
        if (f.id !== 'custom_features') { return; }
        (f.settings.FEATURES || []).forEach(function (t) {
            var deps = (t.settings.DEPENDENCIES || '').split(',');
            if (t.settings.TYPE === 'block' && deps.indexOf('modbus_master') !== -1) {
                requestBlockIds[t.settings.FEATURE_ID] = true;
            }
        });
    });
    project.features.forEach(function (n) {
        var s = n.settings || {};
        var isRequest = n.id === 'node_modbus_write' || requestBlockIds[n.id] === true;
        if (!isRequest || s.DEVICE !== '' || (s.PROTOCOL || 'modbus_RTU') !== 'modbus_RTU') { return; }
        if (rtuBus[s.SERIAL_PORT] === undefined) { rtuBus[s.SERIAL_PORT] = nextRtu; nextRtu += 1; }
    });
    var portRef = feature.settings.SERIAL_PORT || '';
    var port = project.features.filter(function (f) {
        return portRef !== '' && f.settings && (f.settings.ID === portRef || f.settings.NAME === portRef);
    })[0];
    var busIdx = port ? rtuBus[port.settings.ID] : undefined;
    lines.push('#define MBREQ_' + id + '_DYNAMIC_TCP 0');
    lines.push('#define MBREQ_' + id + '_CLIENT ' + (busIdx === undefined ? '(-1)' : 'mb_client_rtu_' + busIdx));
    return lines.join('\n');
})()
}}

#ifndef MBREQ_MAX_REGS
#define MBREQ_MAX_REGS 125 /* Modbus limit for one read; requests are clamped to it */
#endif

/* Fields ordered widest-first so the layout has no interior padding holes. */
struct mbreq_{{feature.settings.ID}}_msg {
    uint16_t register_address;  /* start address / coil address */
    uint16_t data;              /* value to write (FC05 0/1, FC06 register value) */
    uint16_t count;             /* registers / coils to read */
    uint8_t  function_code;     /* Modbus function code 1..6 */
    uint8_t  device_id;         /* Modbus unit id */
};

/* Depth 8: the handler drains one message per work run and posts only come from
 * flow triggers. A full queue drops the newest post (the request is skipped). */
K_MSGQ_DEFINE(mbreq_{{feature.settings.ID}}_msgq,
              sizeof(struct mbreq_{{feature.settings.ID}}_msg), 8, 4);

static void mbreq_{{feature.settings.ID}}_handler(struct k_work *work);
K_WORK_DEFINE(mbreq_{{feature.settings.ID}}_work, mbreq_{{feature.settings.ID}}_handler);

/* Producer: copy the parameters into the msgq and kick the drain work.
 * Non-blocking, safe from any handler context. */
static inline void mbreq_{{feature.settings.ID}}_post(uint8_t function_code, uint8_t device_id, uint16_t register_address, uint16_t count, uint16_t data) {
    struct mbreq_{{feature.settings.ID}}_msg msg = {
        .register_address = register_address,
        .data = data,
        .count = count,
        .function_code = function_code,
        .device_id = device_id,
    };
    (void)k_msgq_put(&mbreq_{{feature.settings.ID}}_msgq, &msg, K_NO_WAIT);
    k_work_submit_to_queue(&low_priority_wq, &mbreq_{{feature.settings.ID}}_work);
}

/* Runs on low_priority_wq: one blocking Modbus transaction per run, then
 * resubmits itself while the msgq is non-empty so other work interleaves. */
static void mbreq_{{feature.settings.ID}}_handler(struct k_work *work) {
    ARG_UNUSED(work);

    struct mbreq_{{feature.settings.ID}}_msg msg = {};
    if (k_msgq_get(&mbreq_{{feature.settings.ID}}_msgq, &msg, K_NO_WAIT) != 0) {
        return;
    }
    int function_code = msg.function_code;
    int device_id = msg.device_id;
    int register_address = msg.register_address;
    uint16_t count = msg.count;
    if (count < 1) {
        count = 1;
    }
    if (count > MBREQ_MAX_REGS) {
        count = MBREQ_MAX_REGS;
    }
    float response_data = 0.0f;
    int error = 0;

#if MBREQ_{{feature.settings.ID}}_DYNAMIC_TCP
    /* Host/port may reference variables, so they are evaluated on every request.
     * The pool reuses an already open socket to the same slave. */
    string mb_host = {{$DEVICEIP}};
    string mb_port = {{$DEVICEPORT}};
    int mb_client = modbus_client_pool_acquire(mb_host.c_str(), (uint16_t)atoi(mb_port.c_str()));
    if (mb_client < 0) {
        LOG_WRN("mbreq_{{feature.settings.ID}}: pool acquire %s:%s failed (%d)", mb_host.c_str(), mb_port.c_str(), mb_client);
        error = -ENOTCONN;
    }
#else
    int mb_client = MBREQ_{{feature.settings.ID}}_CLIENT;
    if (mb_client < 0) {
        LOG_WRN("mbreq_{{feature.settings.ID}}: client not initialized");
        error = -ENOTCONN;
    }
#endif
    if (error == 0 && !modbus_client_is_connected(mb_client)) {
        /* TCP connects lazily; without device polling on this bus nothing else
         * kicks it, so attempt a bounded connect here (no-op for RTU). */
        error = modbus_client_connect(mb_client);
        if (error != 0) {
            LOG_WRN("mbreq_{{feature.settings.ID}}: not connected (%d)", error);
        }
    }
    if (error == 0) {
        switch (function_code) {
        case 1: { /* Read Coils */
            uint8_t coil_values[(MBREQ_MAX_REGS + 7) / 8] = {0};
            error = modbus_client_read_coils(mb_client, (uint8_t)device_id, (uint16_t)register_address, coil_values, count);
            response_data = (float)(coil_values[0] & 1);
            break;
        }
        case 2: { /* Read Discrete Inputs */
            uint8_t di_values[(MBREQ_MAX_REGS + 7) / 8] = {0};
            error = modbus_client_read_dinputs(mb_client, (uint8_t)device_id, (uint16_t)register_address, di_values, count);
            response_data = (float)(di_values[0] & 1);
            break;
        }
        case 3: { /* Read Holding Registers */
            uint16_t reg_values[MBREQ_MAX_REGS] = {0};
            error = modbus_client_read_holding_regs(mb_client, (uint8_t)device_id, (uint16_t)register_address, reg_values, count);
            response_data = modbus_parse_registers(reg_values, count, {{ feature.settings.VARTYPE === 'FLOAT' ? 'MODBUS_DATA_FLOAT' : (feature.settings.VARTYPE === 'SIGNED_INTEGER' ? 'MODBUS_DATA_SIGNED' : 'MODBUS_DATA_UNSIGNED') }}, {{ feature.settings.ENDIAN === 'LITTLE' ? 'MODBUS_ENDIAN_LITTLE' : 'MODBUS_ENDIAN_BIG' }});
            break;
        }
        case 4: { /* Read Input Registers */
            uint16_t reg_values[MBREQ_MAX_REGS] = {0};
            error = modbus_client_read_input_regs(mb_client, (uint8_t)device_id, (uint16_t)register_address, reg_values, count);
            response_data = modbus_parse_registers(reg_values, count, {{ feature.settings.VARTYPE === 'FLOAT' ? 'MODBUS_DATA_FLOAT' : (feature.settings.VARTYPE === 'SIGNED_INTEGER' ? 'MODBUS_DATA_SIGNED' : 'MODBUS_DATA_UNSIGNED') }}, {{ feature.settings.ENDIAN === 'LITTLE' ? 'MODBUS_ENDIAN_LITTLE' : 'MODBUS_ENDIAN_BIG' }});
            break;
        }
        case 5: { /* Write Single Coil */
            bool coil_state = (msg.data != 0);
            error = modbus_client_write_coil(mb_client, (uint8_t)device_id, (uint16_t)register_address, coil_state);
            response_data = (float)coil_state;
            break;
        }
        case 6: { /* Write Single Register */
            error = modbus_client_write_holding_reg(mb_client, (uint8_t)device_id, (uint16_t)register_address, msg.data);
            response_data = (float)msg.data;
            break;
        }
        default:
            LOG_WRN("mbreq_{{feature.settings.ID}}: unsupported function code %d", function_code);
            error = -ENOTSUP;
            break;
        }
        if (error == 6) {
            /* mismatch data or busy: treated as a response, like the built-in block */
            error = 0;
        }
    }
    if (error != 0) {
        LOG_WRN("mbreq_{{feature.settings.ID}} err: %d (fc %d unit %d addr %d)", error, function_code, device_id, register_address);
    }
    (void)response_data;
    (void)device_id;
    (void)register_address;
    (void)error;
    /* Done output: response_data, device_id, register_address, error */
    {{block.output}}

    /* One bounded transaction per run; yield the queue, then keep draining. */
    if (k_msgq_num_used_get(&mbreq_{{feature.settings.ID}}_msgq) > 0) {
        k_work_submit_to_queue(&low_priority_wq, &mbreq_{{feature.settings.ID}}_work);
    }
}

/* The request is queued and runs on low_priority_wq; the Done output fires from
 * there with the result, so the output variables are unused at the trigger. */
(void)response_data;
(void)device_id;
(void)register_address;
(void)error;
uint8_t mb_unit_id = (uint8_t)({{$DEVICEID}});
#ifdef MBREQ_{{feature.settings.ID}}_DEVICE_UNIT_ID
/* Linked serial device: the unit id comes from the device configuration. */
mb_unit_id = (uint8_t)MBREQ_{{feature.settings.ID}}_DEVICE_UNIT_ID;
#endif
mbreq_{{feature.settings.ID}}_post((uint8_t)({{$FUNCTIONCODE}}), mb_unit_id, (uint16_t)({{$REGISTER_ADDRESS}}), (uint16_t)({{$LENGTH}}), (uint16_t)({{$DATA}}));

settings.CUSTOM_UI:
function Information() {
    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8, fontSize: 12, color: '#666' }}>
            <div>
                This block creates or updates one custom SNMP object. Its full OID is &lt;sysObjectID&gt;.1.&lt;Object OID (column)&gt;.0. When the block runs, Value becomes the value returned by the next SNMP GET request.
            </div>
            <div>
                Data Type and Access are applied only when a column is first created. If multiple blocks use the same column, the first block defines its type and access; later blocks only update its value.
            </div>
            <div>
                The SNMP feature needs a free MIB Object Table Size slot. Do not use a column already used by the built-in SNMP MIB objects.
            </div>
            <div>Output: none.</div>
        </div>
    );
}

return Information;

settings.CODE:
/* ---- Appended by the custom SNMP blocks (SNMP Set Custom Object / On SNMP
 * Receive), emitted once. The SNMP feature exposes set-by-slot but no
 * read-by-slot, and the object table is static to this translation unit, so
 * the accessors are added here, next to it. They mirror
 * snmp_config_object_set_int/_str and depend on the table layout generated by
 * the SNMP feature (snmp_priv_objects[].in_use/int_val/str_val). */
#ifdef SNMP_PRIV_OBJECT_MAX
int32_t snmp_rt_object_get_int(int index)
{
    if ((index >= 0) && (index < SNMP_PRIV_OBJECT_MAX) && snmp_priv_objects[index].in_use) {
        return (int32_t)snmp_priv_objects[index].int_val;
    }
    return 0;
}

const char *snmp_rt_object_get_str(int index)
{
    if ((index >= 0) && (index < SNMP_PRIV_OBJECT_MAX) && snmp_priv_objects[index].in_use) {
        return snmp_priv_objects[index].str_val;
    }
    return "";
}
#else /* MIB Object Table Size is 0: no table to read */
int32_t snmp_rt_object_get_int(int index) { (void)index; return 0; }
const char *snmp_rt_object_get_str(int index) { (void)index; return ""; }
#endif

/* Shared runtime SNMP object helper (see snmp_rt_obj_helper_def). */
#define SNMP_RT_OBJ_MAX 128
typedef void (*snmp_rt_handler_t)(const char *oid, const char *value);
/* Read-by-slot accessors appended to snmp_config.c by the same blocks. */
extern "C" int32_t snmp_rt_object_get_int(int index);
extern "C" const char *snmp_rt_object_get_str(int index);
static int snmp_rt_obj_acquire(uint32_t oid, snmp_obj_type_t type, snmp_obj_access_t access);
static void snmp_rt_obj_set_value(int slot, const char *text);
static snmp_obj_type_t snmp_rt_type_parse(const char *text);
static snmp_obj_access_t snmp_rt_access_parse(const char *text);
static void snmp_rt_subscribe(snmp_rt_handler_t handler);
static void snmp_rt_dispatch(uint32_t column, const char *value);

/* Shared by the "SNMP Set Custom Object" and "On SNMP Receive" blocks (emitted
 * once). Keeps a map of the objects registered at runtime with the agent, so a
 * column can be resolved to its slot and read back after a manager SET. Every
 * runtime object gets a per-index trampoline as its set callback (the agent's
 * callback carries no context), and every SET is fanned out to the subscribed
 * handlers as (full dotted OID, value as text). Runs on the SNMP work queue;
 * the strings are only valid for the duration of the call. */
#define SNMP_RT_BASE_OID "{{(function () {
    var agent = null;
    for (var i = 0; i < project.features.length; i++) {
        if (project.features[i].id === 'snmp_agent') { agent = project.features[i]; break; }
    }
    var sys = agent && agent.settings.SYSOBJECTID ? String(agent.settings.SYSOBJECTID).trim().replace(/^\.+|\.+$/g, '') : '';
    return sys === '' ? '1.3.6.1.4.1.20738' : sys;
})()}}"
#define SNMP_RT_HANDLER_MAX 8

struct snmp_rt_obj {
    uint32_t oid;        /* column under the private group node */
    int      slot;       /* agent table slot                     */
    bool     is_string;  /* octet-string-backed vs integer       */
};
static struct snmp_rt_obj  snmp_rt_objs[SNMP_RT_OBJ_MAX];
static int                 snmp_rt_obj_count = 0;
static snmp_rt_handler_t   snmp_rt_handlers[SNMP_RT_HANDLER_MAX];
static int                 snmp_rt_handler_count = 0;

static void snmp_rt_subscribe(snmp_rt_handler_t handler)
{
    if (handler != NULL && snmp_rt_handler_count < SNMP_RT_HANDLER_MAX) {
        snmp_rt_handlers[snmp_rt_handler_count++] = handler;
    }
}

/* Fan a SET out to every subscriber. column is the object's column; the full
 * instance OID is <sysObjectID>.1.<column>.0. */
static void snmp_rt_dispatch(uint32_t column, const char *value)
{
    static char snmp_rt_oid_buf[64];
    snprintf(snmp_rt_oid_buf, sizeof(snmp_rt_oid_buf), SNMP_RT_BASE_OID ".1.%u.0", (unsigned)column);
    for (int i = 0; i < snmp_rt_handler_count; i++) {
        snmp_rt_handlers[i](snmp_rt_oid_buf, value ? value : "");
    }
}

static void snmp_rt_notify(int index)
{
    const struct snmp_rt_obj *o = &snmp_rt_objs[index];
    if (o->is_string) {
        snmp_rt_dispatch(o->oid, snmp_rt_object_get_str(o->slot));
    } else {
        static char snmp_rt_val_buf[16];
        snprintf(snmp_rt_val_buf, sizeof(snmp_rt_val_buf), "%ld", (long)snmp_rt_object_get_int(o->slot));
        snmp_rt_dispatch(o->oid, snmp_rt_val_buf);
    }
}

#define SNMP_RT_TRAMP(n) static void snmp_rt_tramp_##n(void) { snmp_rt_notify(n); }
