/* Case-insensitive substring test used to accept either the enum names
 * (SNMP_OBJ_TYPE_GAUGE32) or plain words ("gauge", "Gauge32") from a table. */
static bool snmp_rt_has_word(const char *text, const char *word)
{
    char lower[48];
    size_t n = 0;
    for (; text != NULL && text[n] != '\0' && n < sizeof(lower) - 1; n++) {
        char c = text[n];
        lower[n] = (c >= 'A' && c <= 'Z') ? (char)(c + 32) : c;
    }
    lower[n] = '\0';
    return strstr(lower, word) != NULL;
}

static snmp_obj_type_t snmp_rt_type_parse(const char *text)
{
    if (snmp_rt_has_word(text, "string") || snmp_rt_has_word(text, "octet")) return SNMP_OBJ_TYPE_STRING;
    if (snmp_rt_has_word(text, "object") || snmp_rt_has_word(text, "oid"))   return SNMP_OBJ_TYPE_OBJECT_ID;
    if (snmp_rt_has_word(text, "counter64"))                                  return SNMP_OBJ_TYPE_COUNTER64;
    if (snmp_rt_has_word(text, "counter"))                                    return SNMP_OBJ_TYPE_COUNTER32;
    if (snmp_rt_has_word(text, "gauge") || snmp_rt_has_word(text, "unsigned")) return SNMP_OBJ_TYPE_GAUGE32;
    if (snmp_rt_has_word(text, "tick"))                                       return SNMP_OBJ_TYPE_TIMETICKS;
    if (snmp_rt_has_word(text, "opaque"))                                     return SNMP_OBJ_TYPE_OPAQUE;
    if (snmp_rt_has_word(text, "ip"))                                         return SNMP_OBJ_TYPE_IP_ADDRESS;
    return SNMP_OBJ_TYPE_INTEGER;
}

static snmp_obj_access_t snmp_rt_access_parse(const char *text)
{
    if (snmp_rt_has_word(text, "write") || snmp_rt_has_word(text, "rw")) return SNMP_OBJ_ACCESS_READ_WRITE;
    return SNMP_OBJ_ACCESS_READ_ONLY;
}

/* Idempotent per column: returns the existing slot or registers the object
 * once with the agent (the first caller's type/access win) and hooks its set
 * callback. Returns -1 when the agent table or this map is full. Capacity is
 * the SNMP feature's "MIB Object Table Size" setting. */
static int snmp_rt_obj_acquire(uint32_t oid, snmp_obj_type_t type, snmp_obj_access_t access)
{
    for (int i = 0; i < snmp_rt_obj_count; i++) {
        if (snmp_rt_objs[i].oid == oid) {
            return snmp_rt_objs[i].slot;
        }
    }
    if (snmp_rt_obj_count >= SNMP_RT_OBJ_MAX) {
        return -1;
    }
    int slot = snmp_config_add_object(oid, type, access);
    if (slot >= 0) {
        int index = snmp_rt_obj_count;
        snmp_rt_objs[index].oid       = oid;
        snmp_rt_objs[index].slot      = slot;
        snmp_rt_objs[index].is_string = (type == SNMP_OBJ_TYPE_STRING)
                                     || (type == SNMP_OBJ_TYPE_OBJECT_ID)
                                     || (type == SNMP_OBJ_TYPE_OPAQUE);
        snmp_rt_obj_count++;
        snmp_config_object_on_set(slot, snmp_rt_tramps[index]);
    }
    return slot;
}

/* Store a text value into a runtime object using the type it was created with. */
static void snmp_rt_obj_set_value(int slot, const char *text)
{
    for (int i = 0; i < snmp_rt_obj_count; i++) {
        if (snmp_rt_objs[i].slot == slot) {
            if (snmp_rt_objs[i].is_string) {
                snmp_config_object_set_str(slot, text ? text : "");
            } else {
                snmp_config_object_set_int(slot, (int32_t)atoi(text ? text : "0"));
            }
            return;
        }
    }
}

