/*
 * Update or insert one row using the device identity key:
 * DEVICE_ID + REG_ADDR + OID_COLUMN. NAME is row data.
 *
 * result = 0: matching row updated
 * result = 1: new row inserted
 * result < 0: FSDB error
 */
constexpr size_t UPSERT_ROW_CAPACITY = 128;
result = FSDB_ERR_INVALID_PARAM;

string upsert_table = {{$TABLE}};
string upsert_name = {{$NAME}};
float upsert_device_id = (float)({{$DEVICE_ID}});
float upsert_reg_addr = (float)({{$REG_ADDR}});
float upsert_oid_column = (float)({{$OID_COLUMN}});
string upsert_hash_id = {{$HASH_ID}};
string upsert_value = {{$VALUE}};

const fsdb_schema_t *schema = get_table_schema(upsert_table.c_str());

do {
    if (schema == NULL || schema->column_count == 0 ||
        strcmp(schema->columns[0].name, "id") != 0 ||
        upsert_hash_id.empty()) {
        break;
    }

    const fsdb_column_t *name_column = NULL;
    const fsdb_column_t *device_id_column = NULL;
    const fsdb_column_t *reg_addr_column = NULL;
    const fsdb_column_t *oid_column_column = NULL;
    const fsdb_column_t *hash_id_column = NULL;
    const fsdb_column_t *value_column = NULL;
    uint16_t name_offset = 0;
    uint16_t device_id_offset = 0;
    uint16_t reg_addr_offset = 0;
    uint16_t oid_column_offset = 0;
    uint16_t hash_id_offset = 0;
    uint16_t value_offset = 0;
    uint16_t offset = 0;

    for (int i = 0; i < schema->column_count; ++i) {
        const fsdb_column_t *column = &schema->columns[i];

        if (strcmp(column->name, "NAME") == 0) {
            name_column = column;
            name_offset = offset;
        } else if (strcmp(column->name, "DEVICE_ID") == 0) {
            device_id_column = column;
            device_id_offset = offset;
        } else if (strcmp(column->name, "REG_ADDR") == 0) {
            reg_addr_column = column;
            reg_addr_offset = offset;
        } else if (strcmp(column->name, "OID_COLUMN") == 0) {
            oid_column_column = column;
            oid_column_offset = offset;
        } else if (strcmp(column->name, "HASH_ID") == 0) {
            hash_id_column = column;
            hash_id_offset = offset;
        } else if (strcmp(column->name, "VALUE") == 0) {
            value_column = column;
            value_offset = offset;
        }

        offset += fsdb_type_size(column->type, column->size);
    }

    if (name_column == NULL || device_id_column == NULL ||
        reg_addr_column == NULL || oid_column_column == NULL ||
        hash_id_column == NULL || value_column == NULL ||
        name_column->type != FSDB_TYPE_STRING ||
        device_id_column->type != FSDB_TYPE_FLOAT ||
        reg_addr_column->type != FSDB_TYPE_FLOAT ||
        oid_column_column->type != FSDB_TYPE_FLOAT ||
        hash_id_column->type != FSDB_TYPE_STRING ||
        value_column->type != FSDB_TYPE_STRING ||
        hash_id_column->size < 17) {
        result = FSDB_ERR_COLUMN_NOT_FOUND;
        break;
    }

    fsdb_handle_t db;
    int fsdb_result = fsdb_open(&db, schema);

    if (fsdb_result != FSDB_OK && fsdb_result != FSDB_ERR_RECOVERED) {
        result = fsdb_result;
        break;
    }

    if (db.user_data_size > UPSERT_ROW_CAPACITY ||
        (uint32_t)name_offset + name_column->size > db.user_data_size ||
        (uint32_t)device_id_offset + sizeof(float) > db.user_data_size ||
        (uint32_t)reg_addr_offset + sizeof(float) > db.user_data_size ||
        (uint32_t)oid_column_offset + sizeof(float) > db.user_data_size ||
        (uint32_t)hash_id_offset + hash_id_column->size > db.user_data_size ||
        (uint32_t)value_offset + value_column->size > db.user_data_size) {
        fsdb_close(&db);
        result = FSDB_ERR_NO_SPACE;
        break;
    }

    int row_count = fsdb_count(&db);

    if (row_count < 0) {
        fsdb_close(&db);
        result = row_count;
        break;
    }

    uint8_t row[UPSERT_ROW_CAPACITY] = {};
    bool completed = false;

    for (uint32_t row_offset = 0;
         row_offset < (uint32_t)row_count;
         ++row_offset) {
        fsdb_result = fsdb_read_by_offset(&db, row_offset, row, NULL);

        if (fsdb_result != FSDB_OK) {
            fsdb_close(&db);
            result = fsdb_result;
            completed = true;
            break;
        }

        float stored_device_id = 0.0f;
        float stored_reg_addr = 0.0f;
        float stored_oid_column = 0.0f;
        memcpy(&stored_device_id, row + device_id_offset, sizeof(float));
        memcpy(&stored_reg_addr, row + reg_addr_offset, sizeof(float));
        memcpy(&stored_oid_column, row + oid_column_offset, sizeof(float));

        bool matches =
            stored_device_id == upsert_device_id &&
            stored_reg_addr == upsert_reg_addr &&
            stored_oid_column == upsert_oid_column;

        if (!matches) {
            continue;
        }

        uint32_t logical_row_id = 0;
        memcpy(&logical_row_id, row, sizeof(logical_row_id));

        strncpy((char *)(row + name_offset),
                upsert_name.c_str(),
                name_column->size - 1);
        row[name_offset + name_column->size - 1] = 0;

        strncpy((char *)(row + hash_id_offset),
                upsert_hash_id.c_str(),
                hash_id_column->size - 1);
        row[hash_id_offset + hash_id_column->size - 1] = 0;

        strncpy((char *)(row + value_offset),
                upsert_value.c_str(),
                value_column->size - 1);
        row[value_offset + value_column->size - 1] = 0;

        fsdb_result = fsdb_update(&db, logical_row_id, row);
        fsdb_close(&db);
        result = (fsdb_result == FSDB_OK) ? 0 : fsdb_result;
        completed = true;
        break;
    }

    if (completed) {
        break;
    }

    memset(row, 0, sizeof(row));

    strncpy((char *)(row + name_offset),
            upsert_name.c_str(),
            name_column->size - 1);
    row[name_offset + name_column->size - 1] = 0;
    memcpy(row + device_id_offset, &upsert_device_id, sizeof(float));
    memcpy(row + reg_addr_offset, &upsert_reg_addr, sizeof(float));
    memcpy(row + oid_column_offset, &upsert_oid_column, sizeof(float));

    strncpy((char *)(row + hash_id_offset),
            upsert_hash_id.c_str(),
            hash_id_column->size - 1);
    row[hash_id_offset + hash_id_column->size - 1] = 0;

    strncpy((char *)(row + value_offset),
            upsert_value.c_str(),
            value_column->size - 1);
    row[value_offset + value_column->size - 1] = 0;

    fsdb_result = fsdb_insert(&db, row, NULL);
    fsdb_close(&db);
    result = (fsdb_result == FSDB_OK) ? 1 : fsdb_result;
} while (false);

