/*
 * Generate a deterministic 64-bit FNV-1a hash for:
 * DEVICE_ID + REG_ADDR + OID_COLUMN. NAME is a label.
 *
 * hash_id is a 16-character uppercase hexadecimal string.
 * It is empty when a numeric input is negative, fractional, or outside
 * the exactly representable unsigned-integer range.
 */
constexpr uint64_t ROW_KEY_HASH_OFFSET = 14695981039346656037ULL;
constexpr uint64_t ROW_KEY_HASH_PRIME = 1099511628211ULL;
constexpr float ROW_KEY_HASH_MAX_EXACT_UINT = 16777215.0f;

float hash_device_id_input = (float)({{$DEVICE_ID}});
float hash_reg_addr_input = (float)({{$REG_ADDR}});
float hash_oid_column_input = (float)({{$OID_COLUMN}});
char hash_text[17] = {};
hash_id = hash_text;

if (hash_device_id_input >= 0.0f &&
    hash_device_id_input <= ROW_KEY_HASH_MAX_EXACT_UINT &&
    hash_reg_addr_input >= 0.0f &&
    hash_reg_addr_input <= ROW_KEY_HASH_MAX_EXACT_UINT &&
    hash_oid_column_input >= 0.0f &&
    hash_oid_column_input <= ROW_KEY_HASH_MAX_EXACT_UINT) {
    uint32_t hash_device_id = (uint32_t)hash_device_id_input;
    uint32_t hash_reg_addr = (uint32_t)hash_reg_addr_input;
    uint32_t hash_oid_column = (uint32_t)hash_oid_column_input;

    if ((float)hash_device_id == hash_device_id_input &&
        (float)hash_reg_addr == hash_reg_addr_input &&
        (float)hash_oid_column == hash_oid_column_input) {
        uint64_t hash = ROW_KEY_HASH_OFFSET;

        auto hash_byte = [&](uint8_t value) {
            hash ^= value;
            hash *= ROW_KEY_HASH_PRIME;
        };

        auto hash_uint32 = [&](uint32_t value) {
            for (unsigned int byte_index = 0;
                 byte_index < 4;
                 ++byte_index) {
                hash_byte((uint8_t)(value >> (byte_index * 8)));
            }
        };

        hash_uint32(hash_device_id);
        hash_uint32(hash_reg_addr);
        hash_uint32(hash_oid_column);

        snprintf(hash_text,
                 sizeof(hash_text),
                 "%016llX",
                 (unsigned long long)hash);
    }
}

