#ifndef TABLE_MUTATION_RUNTIME_DECLARED
#define TABLE_MUTATION_RUNTIME_DECLARED
#define TABLE_MUTATION_RUNTIME_AVAILABLE 1

static const fsdb_schema_t *get_table_schema(const char *name);
typedef void (*table_mutation_listener_t)(const char *table_name, bool notify);

static void table_mutation_runtime_init(void);
static void table_mutation_subscribe(table_mutation_listener_t listener);
static void table_mutation_suppress_begin(const char *table_name);
