#ifndef TABLE_MUTATION_RUNTIME_DEFINED
#define TABLE_MUTATION_RUNTIME_DEFINED

#define TABLE_MUTATION_MAX_LISTENERS 4
#define TABLE_MUTATION_MAX_PENDING 16
#define TABLE_MUTATION_MAX_SUPPRESSED 16

struct table_mutation_suppression {
    char table_name[FSDB_MAX_TABLE_NAME];
    uint16_t depth;
};

static table_mutation_listener_t
    table_mutation_listeners[TABLE_MUTATION_MAX_LISTENERS];
static size_t table_mutation_listener_count;
static struct k_work table_mutation_work;
static struct k_spinlock table_mutation_lock;
static char table_mutation_pending[TABLE_MUTATION_MAX_PENDING]
                                  [FSDB_MAX_TABLE_NAME];
static size_t table_mutation_pending_count;
static struct table_mutation_suppression
    table_mutation_suppressed[TABLE_MUTATION_MAX_SUPPRESSED];
static size_t table_mutation_suppressed_count;
static bool table_mutation_initialized;

static bool table_mutation_is_suppressed(const char *table_name)
{
    if (table_name == NULL) {
        return false;
    }

    bool suppressed = false;
    k_spinlock_key_t key = k_spin_lock(&table_mutation_lock);

    for (size_t i = 0; i < table_mutation_suppressed_count; ++i) {
        if (strcmp(table_mutation_suppressed[i].table_name, table_name) == 0) {
            suppressed = true;
            break;
        }
    }

    k_spin_unlock(&table_mutation_lock, key);
    return suppressed;
}

static void table_mutation_dispatch(const char *table_name, bool notify)
{
    if (table_name == NULL) {
        return;
    }

    for (size_t i = 0; i < table_mutation_listener_count; ++i) {
        table_mutation_listeners[i](table_name, notify);
    }
}

static void table_mutation_work_handler(struct k_work *work)
{
    (void)work;

    for (;;) {
        char table_name[FSDB_MAX_TABLE_NAME];
        k_spinlock_key_t key = k_spin_lock(&table_mutation_lock);

        if (table_mutation_pending_count == 0) {
            k_spin_unlock(&table_mutation_lock, key);
            break;
        }

        --table_mutation_pending_count;
        strncpy(table_name,
                table_mutation_pending[table_mutation_pending_count],
                sizeof(table_name) - 1);
        table_name[sizeof(table_name) - 1] = '\0';
        k_spin_unlock(&table_mutation_lock, key);

        if (!table_mutation_is_suppressed(table_name)) {
            table_mutation_dispatch(table_name, true);
        }
    }
}

static void table_mutation_runtime_init(void)
{
    if (!table_mutation_initialized) {
        k_work_init(&table_mutation_work, table_mutation_work_handler);
        table_mutation_initialized = true;
    }
}

static void table_mutation_subscribe(table_mutation_listener_t listener)
{
    if (listener == NULL) {
        return;
    }

    table_mutation_runtime_init();

    for (size_t i = 0; i < table_mutation_listener_count; ++i) {
        if (table_mutation_listeners[i] == listener) {
            return;
        }
    }

    if (table_mutation_listener_count < TABLE_MUTATION_MAX_LISTENERS) {
        table_mutation_listeners[table_mutation_listener_count++] = listener;
    }
}

static void table_mutation_schedule(const char *table_name)
{
    if (!table_mutation_initialized || table_name == NULL ||
        table_name[0] == '\0' || table_mutation_is_suppressed(table_name)) {
        return;
    }

    bool queued = false;
    k_spinlock_key_t key = k_spin_lock(&table_mutation_lock);

    for (size_t i = 0; i < table_mutation_pending_count; ++i) {
        if (strcmp(table_mutation_pending[i], table_name) == 0) {
            queued = true;
            break;
        }
    }

    if (!queued && table_mutation_pending_count < TABLE_MUTATION_MAX_PENDING) {
        strncpy(table_mutation_pending[table_mutation_pending_count],
                table_name, FSDB_MAX_TABLE_NAME - 1);
        table_mutation_pending[table_mutation_pending_count]
                              [FSDB_MAX_TABLE_NAME - 1] = '\0';
        ++table_mutation_pending_count;
        queued = true;
    }

    k_spin_unlock(&table_mutation_lock, key);

    if (queued) {
        k_work_submit_to_queue(&low_priority_wq, &table_mutation_work);
    }
}

static void table_mutation_suppress_begin(const char *table_name)
{
    if (table_name == NULL || table_name[0] == '\0') {
        return;
    }

    table_mutation_runtime_init();
    k_spinlock_key_t key = k_spin_lock(&table_mutation_lock);

    for (size_t i = 0; i < table_mutation_suppressed_count; ++i) {
        if (strcmp(table_mutation_suppressed[i].table_name, table_name) == 0) {
            ++table_mutation_suppressed[i].depth;
            k_spin_unlock(&table_mutation_lock, key);
            return;
        }
    }

    if (table_mutation_suppressed_count < TABLE_MUTATION_MAX_SUPPRESSED) {
        struct table_mutation_suppression *entry =
            &table_mutation_suppressed[table_mutation_suppressed_count++];
        strncpy(entry->table_name, table_name, sizeof(entry->table_name) - 1);
        entry->table_name[sizeof(entry->table_name) - 1] = '\0';
        entry->depth = 1;
    }

    k_spin_unlock(&table_mutation_lock, key);
}

static void table_mutation_suppress_end(const char *table_name)
{
    if (table_name == NULL || table_name[0] == '\0') {
        return;
    }

    bool final_level = false;
    k_spinlock_key_t key = k_spin_lock(&table_mutation_lock);

    for (size_t i = 0; i < table_mutation_suppressed_count; ++i) {
        if (strcmp(table_mutation_suppressed[i].table_name, table_name) != 0) {
            continue;
        }

        if (table_mutation_suppressed[i].depth > 1) {
            --table_mutation_suppressed[i].depth;
        } else {
            final_level = true;
        }
        break;
    }

    k_spin_unlock(&table_mutation_lock, key);

    if (!final_level) {
        return;
    }

    /* Refresh every listener while this table is still suppressed. */
    table_mutation_dispatch(table_name, false);

    key = k_spin_lock(&table_mutation_lock);
    for (size_t i = 0; i < table_mutation_suppressed_count; ++i) {
        if (strcmp(table_mutation_suppressed[i].table_name, table_name) != 0) {
            continue;
        }

        if (table_mutation_suppressed[i].depth > 1) {
            --table_mutation_suppressed[i].depth;
        } else {
            --table_mutation_suppressed_count;
            table_mutation_suppressed[i] =
                table_mutation_suppressed[table_mutation_suppressed_count];
        }
        break;
    }
    k_spin_unlock(&table_mutation_lock, key);
}

