#define TABLE_MONITOR_MAX_SUBSCRIBERS 16
#define TABLE_MONITOR_MAX_ROW_SIZE 128

typedef void (*table_monitor_handler_t)(void);

struct table_monitor_subscription {
    const char *table_name;
    table_monitor_handler_t handler;
    uint64_t fingerprint;
    bool initialized;
};

static struct table_monitor_subscription
    table_monitor_subscribers[TABLE_MONITOR_MAX_SUBSCRIBERS];
static size_t table_monitor_subscriber_count;
static bool table_monitor_listener_registered;

static uint64_t table_monitor_hash(uint64_t hash,
                                   const void *data,
                                   size_t length)
{
    const uint8_t *bytes = (const uint8_t *)data;

    for (size_t i = 0; i < length; ++i) {
        hash ^= bytes[i];
        hash *= UINT64_C(1099511628211);
    }
    return hash;
}

static bool table_monitor_snapshot(const char *table_name,
                                   uint64_t *fingerprint)
{
    const fsdb_schema_t *schema = get_table_schema(table_name);

    if (schema == NULL || fingerprint == NULL) {
        return false;
    }

    fsdb_handle_t db;
    int result = fsdb_open(&db, schema);

    if (result != FSDB_OK && result != FSDB_ERR_RECOVERED) {
        return false;
    }

    if (db.user_data_size > TABLE_MONITOR_MAX_ROW_SIZE) {
        fsdb_close(&db);
        return false;
    }

    const int row_count = fsdb_count(&db);
    if (row_count < 0) {
        fsdb_close(&db);
        return false;
    }

    uint64_t hash = UINT64_C(1469598103934665603);
    hash = table_monitor_hash(hash, &row_count, sizeof(row_count));
    hash = table_monitor_hash(hash, &db.user_data_size,
                              sizeof(db.user_data_size));

    for (uint32_t index = 0; index < (uint32_t)row_count; ++index) {
        uint8_t row[TABLE_MONITOR_MAX_ROW_SIZE] = {};
        uint32_t row_id = 0;

        result = fsdb_read_by_offset(&db, index, row, &row_id);
        if (result != FSDB_OK) {
            fsdb_close(&db);
            return false;
        }

        hash = table_monitor_hash(hash, &row_id, sizeof(row_id));
        hash = table_monitor_hash(hash, row, db.user_data_size);
    }

    fsdb_close(&db);
    *fingerprint = hash;
    return true;
}

static void table_monitor_event(const char *table_name, bool notify)
{
    for (size_t i = 0; i < table_monitor_subscriber_count; ++i) {
        struct table_monitor_subscription *subscription =
            &table_monitor_subscribers[i];

        if (strcmp(subscription->table_name, table_name) != 0) {
            continue;
        }

        uint64_t current_fingerprint = 0;
        if (!table_monitor_snapshot(subscription->table_name,
                                    &current_fingerprint)) {
            continue;
        }

        const bool changed = subscription->initialized &&
            current_fingerprint != subscription->fingerprint;
        subscription->fingerprint = current_fingerprint;
        subscription->initialized = true;

        if (notify && changed) {
            subscription->handler();
        }
    }
}

static void table_monitor_subscribe(const char *table_name,
                                    table_monitor_handler_t handler)
{
    if (table_name == NULL || handler == NULL ||
        table_monitor_subscriber_count >= TABLE_MONITOR_MAX_SUBSCRIBERS) {
        return;
    }

    if (!table_monitor_listener_registered) {
        table_mutation_subscribe(table_monitor_event);
        table_monitor_listener_registered = true;
    }

    struct table_monitor_subscription *subscription =
        &table_monitor_subscribers[table_monitor_subscriber_count++];

    subscription->table_name = table_name;
    subscription->handler = handler;
    subscription->initialized = table_monitor_snapshot(
        table_name, &subscription->fingerprint);

    if (!subscription->initialized) {
        LOG_WRN("On Table Changed: invalid table %s", table_name);
    }
}

