/*
 * Strict dotted-decimal IPv4 validation. Each value must contain exactly
 * four decimal octets in the range 0..255. Multi-digit octets with a leading
 * zero are rejected to avoid ambiguous octal-looking addresses.
 *
 * Netmasks must additionally contain contiguous one bits followed by zero
 * bits. Both /0 (0.0.0.0) and /32 (255.255.255.255) are valid masks.
 */
string ipv4_validation_value = {{$VALUE}};
uint8_t ipv4_validation_octets[4] = {};

auto ipv4_parse_dotted_decimal = [](const string &text, uint8_t octets[4]) {
    if (text.empty()) {
        return false;
    }

    size_t position = 0;

    for (size_t octet_index = 0; octet_index < 4; ++octet_index) {
        if (position >= text.size()) {
            return false;
        }

        size_t octet_start = position;
        unsigned int octet = 0;
        size_t digit_count = 0;

        while (position < text.size() &&
               text[position] >= '0' && text[position] <= '9') {
            if (digit_count >= 3) {
                return false;
            }

            octet = octet * 10U + (unsigned int)(text[position] - '0');
            ++position;
            ++digit_count;
        }

        if (digit_count == 0 || octet > 255U ||
            (digit_count > 1 && text[octet_start] == '0')) {
            return false;
        }

        octets[octet_index] = (uint8_t)octet;

        if (octet_index < 3) {
            if (position >= text.size() || text[position] != '.') {
                return false;
            }
            ++position;
        } else if (position != text.size()) {
            return false;
        }
    }

    return true;
};

bool ipv4_validation_result =
    ipv4_parse_dotted_decimal(ipv4_validation_value, ipv4_validation_octets);

if (ipv4_validation_result &&
    {{ feature.settings.VALIDATION_TYPE === 'NETMASK' ? 'true' : 'false' }}) {
    uint32_t netmask =
        ((uint32_t)ipv4_validation_octets[0] << 24) |
        ((uint32_t)ipv4_validation_octets[1] << 16) |
        ((uint32_t)ipv4_validation_octets[2] << 8) |
        (uint32_t)ipv4_validation_octets[3];
    uint32_t inverted_netmask = ~netmask;

    /* 2^n - 1 has only trailing one bits; this includes n=0 and n=32. */
    ipv4_validation_result =
        (inverted_netmask & (inverted_netmask + 1U)) == 0U;
}

is_valid = ipv4_validation_result ? 1 : 0;

