            <select value={selectedId} disabled={fieldDisabled} onChange={function (event) {
                setValue(event.target.value ? '{{$' + event.target.value + '}}' : '');
            }} style={{ width: '100%', minHeight: 24, height: 24 }}>
                <option value="">No parameter (send empty)</option>
                {variables.map(function (variable) {
                    return <option key={variable.id} value={variable.id}>
                        {variable.name + ' (' + (variable.type === 'string' ? 'string' : 'number') + ')'}
                    </option>;
                })}
            </select>
            <div style={{ fontSize: 12, color: '#666' }}>
                Passed internally as command data; this is not a block output.
            </div>
            {error ? <div style={{ color: '#d32f2f' }}>{String(error)}</div> : null}
        </div>
    );
}

return Input;

function Input({ value, setValue, disabled, error, project }) {
    function isNumericType(type) {
        return ['integer', 'float', 'byte', 'word', 'dword', 's', 'f'].indexOf(type) !== -1;
    }
    function getSetting(item, key) {
        if (item && item.getSettingValue) { return item.getSettingValue(key); }
        return item && item.settings ? item.settings[key] : '';
    }
    var variables = (project && project.getVariables ? project.getVariables() : []).map(function (variable) {
        return {
            id: String(variable && variable.getID ? variable.getID() : getSetting(variable, 'ID') || ''),
            name: String(getSetting(variable, 'VARNAME') || ''),
            type: String(getSetting(variable, 'DATATYPE') || '').toLowerCase()
        };
    }).filter(function (variable) {
        return variable.id !== '' && variable.name !== '' &&
            (variable.type === 'string' || isNumericType(variable.type));
    });
    var commandFeature = project && project.getFeature
        ? project.getFeature('commands') : null;
    var nestedCommands = commandFeature && commandFeature.getSettingValue
        ? commandFeature.getSettingValue('COMMANDS') || [] : [];
    var commands = nestedCommands.map(function (command) {
        return {
            id: String(command && command.getID ? command.getID() : getSetting(command, 'ID') || ''),
            name: String(getSetting(command, 'NAME') || '')
        };
    });
    commands = commands.filter(function (command) { return command.id !== '' && command.name !== ''; });

    var variableById = {};
    var commandById = {};
    variables.forEach(function (variable) { variableById[variable.id] = variable; });
    commands.forEach(function (command) { commandById[command.id] = command; });

    function variableId(token) {
        var match = /^\{\{\$(\w+)\}\}$/.exec(String(token || ''));
        return match ? match[1] : '';
    }
    function commandId(token) {
        var prefix = '__COMMAND__:';
        var text = String(token || '');
        return text.indexOf(prefix) === 0 ? text.substring(prefix.length) : '';
    }
    function variableToken(id) { return '{{$' + id + '}}'; }
    function commandToken(id) { return '__COMMAND__:' + id; }
    function readMappings() {
        try {
            var parsed = JSON.parse(value || '[]');
            if (!Array.isArray(parsed)) { return []; }
            var seen = {};
            return parsed.filter(function (mapping) {
                var inputId = variableId(mapping && mapping.input);
                var resultVariableId = variableId(mapping && mapping.result);
                var resultCommandId = commandId(mapping && mapping.result);
                if (!variableById[inputId] || seen[inputId] ||
                    (!variableById[resultVariableId] && !commandById[resultCommandId])) {
                    return false;
                }
                seen[inputId] = true;
                return true;
            });
        } catch (parseError) {
            return [];
        }
    }

    var currentMappings = readMappings();
    var usedInputs = {};
    currentMappings.forEach(function (mapping) { usedInputs[variableId(mapping.input)] = true; });
    function commit(nextMappings) { setValue(JSON.stringify(nextMappings)); }
    function addMapping() {
        var input = variables.filter(function (variable) { return !usedInputs[variable.id]; })[0];
        if (!input || variables.length === 0) { return; }
        commit(currentMappings.concat([{ input: variableToken(input.id), result: variableToken(variables[0].id) }]));
    }
    function updateInput(index, id) {
        if (!variableById[id] || currentMappings.some(function (mapping, currentIndex) {
            return currentIndex !== index && variableId(mapping.input) === id;
        })) { return; }
        var next = currentMappings.slice();
        next[index] = { input: variableToken(id), result: next[index].result };
        commit(next);
    }
    function updateResult(index, token) {
        if (!variableById[variableId(token)] && !commandById[commandId(token)]) { return; }
        var next = currentMappings.slice();
        next[index] = { input: next[index].input, result: token };
        commit(next);
    }
    function removeMapping(index) {
        commit(currentMappings.filter(function (_, currentIndex) { return currentIndex !== index; }));
    }
    function variableLabel(variable) {
        return variable.name + ' (' + (variable.type === 'string' ? 'string' : 'number') + ')';
    }
    var canAdd = !disabled && currentMappings.length < variables.length;

    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            {currentMappings.map(function (mapping, index) {
                var inputId = variableId(mapping.input);
                var inputChoices = variables.filter(function (variable) {
                    return variable.id === inputId || !usedInputs[variable.id];
                });
                return (
                    <div key={mapping.input} style={{ display: 'flex', gap: 8, alignItems: 'center', width: '100%', flexWrap: 'wrap' }}>
                        <select value={inputId} disabled={disabled} onChange={function (event) {
                            updateInput(index, event.target.value);
                        }} style={{ flex: '1 1 0', minWidth: 0, width: 0, maxWidth: '100%', minHeight: 24, height: 24 }}>
                            {inputChoices.map(function (variable) {
                                return <option key={variable.id} value={variable.id}>{variableLabel(variable)}</option>;
                            })}
                        </select>
                        <span>=&gt;</span>
                        <select value={mapping.result} disabled={disabled} onChange={function (event) {
                            updateResult(index, event.target.value);
                        }} style={{ flex: '1 1 0', minWidth: 0, width: 0, maxWidth: '100%', minHeight: 24, height: 24 }}>
                            <optgroup label="Variables">
                                {variables.map(function (variable) {
                                    return <option key={'var-' + variable.id} value={variableToken(variable.id)}>{variableLabel(variable)}</option>;
                                })}
                            </optgroup>
                            {commands.length > 0 ? <optgroup label="Commands">
                                {commands.map(function (command) {
                                    return <option key={'cmd-' + command.id} value={commandToken(command.id)}>{command.name + ' (command)'}</option>;
                                })}
                            </optgroup> : null}
                        </select>
                        <button type="button" disabled={disabled} onClick={function () {
                            removeMapping(index);
                        }} style={{ flex: '0 0 auto', minHeight: 24, height: 24 }}>Remove</button>
                    </div>
                );
            })}
            <button type="button" disabled={!canAdd} onClick={addMapping} style={{ minHeight: 22, height: 22 }}>
                Add Mapping
            </button>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 4, fontSize: 12, color: '#666' }}>
                <div><strong>Left:</strong> unique match variable (String or numeric); commands cannot be selected.</div>
                <div><strong>Right:</strong> result variable (String or numeric) or command. <em>A mapped command runs automatically when Input matches the left variable.</em></div>
                <div><strong>Command Parameter:</strong> optional String or numeric variable passed implicitly as data to the mapped command; when empty, an empty parameter is sent.</div>
            </div>
            {error ? <div style={{ color: '#d32f2f' }}>{String(error)}</div> : null}
        </div>
    );
}

return Input;

function Information() {
    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8, fontSize: 12, color: '#666' }}>
            <div><strong>Input:</strong> maps its current value using String or numeric match variables.</div>
            <div><strong>Right:</strong> may be a result variable or a command. A mapped command runs automatically when its row matches.</div>
            <div><strong>Command Parameter:</strong> optionally selects the variable passed internally as command data. It is not a block output; when empty, an empty payload is sent.</div>
            <div><strong>Compatibility:</strong> existing variable-to-variable mappings remain compatible.</div>
        </div>
    );
}

return Information;

function Output() {
    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8, fontSize: 12, color: '#666' }}>
            <div><strong>result_str (String):</strong> mapped String result, or an empty string (when there is no match or <strong>Right</strong> is a <em>command</em>).</div>
            <div><strong>result_int (numeric):</strong> mapped numeric result, or 0 (when there is no match or <strong>Right</strong> is a <em>command</em>).</div>
            <div><strong>is_found (0 = false, 1 = true):</strong> whether Input matched a mapping.</div>
        </div>
    );
}

return Output;

